void mainImage(out vec4 o, in vec2 f){
  vec2 tex = iChannelResolution[0].xy;
  if (tex.x < 1.0) { o = vec4(0.04, 0.05, 0.08, 1.0); return; }
  vec2 uv = f / iResolution.xy;
  float ra = iResolution.x / iResolution.y, ta = tex.x / tex.y;
  vec2 s = ra > ta ? vec2(1.0, ta / ra) : vec2(ra / ta, 1.0);
  o = vec4(texture(iChannel0, (uv - 0.5) * s + 0.5).rgb, 1.0);
}

void mainImage(out vec4 o, in vec2 f){
  vec2 uv = f / iResolution.xy;
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float t = iTime * 0.6;
  float r = length(p);
  float a = atan(p.y, p.x);
  float w = sin(r * 22.0 - t * 4.0 + sin(a * 5.0 + t) * 1.5);
  vec3 c1 = vec3(1.0, 0.36, 0.62), c2 = vec3(0.2, 0.95, 0.8), c3 = vec3(1.0, 0.86, 0.2);
  vec3 col = mix(c1, c2, smoothstep(-0.6, 0.6, w));
  col = mix(col, c3, smoothstep(0.85, 1.0, sin(a * 3.0 - t * 2.0)) * 0.6);
  float edge = smoothstep(0.0, 0.02, min(min(uv.x, 1.0 - uv.x), min(uv.y, 1.0 - uv.y)));
  o = vec4(col, 0.82 * edge);
}
